require('reflect-metadata');
const { plainToInstance } = require('class-transformer');
const { validateOrReject, IsEmail, IsEnum, IsBoolean } = require('class-validator');
const Redis = require('ioredis');

const app = express();
app.use(express.json());
const redis = new Redis(process.env.REDIS_URL);

enum Frequency {
  NONE = 'NONE',
  WEEKLY = 'WEEKLY',
  MONTHLY = 'MONTHLY'
}

class DigestSettingsDto {
  @IsEmail()
  recipientEmail;

  @IsEnum(Frequency)
  frequency;

  @IsBoolean()
  includePromotions;
}

app.put('/api/marketing/digest', async (req, res) => {
  const dto = plainToInstance(DigestSettingsDto, req.body);
  try {
    await validateOrReject(dto);
  } catch (e) {
    return res.status(400).json({ error: 'Invalid digest options' });
  }

  // Updates email preference hash keyed by recipientEmail without verifying user identity
  await redis.hset(`marketing_prefs:${dto.recipientEmail}`, {
    frequency: dto.frequency,
    includePromotions: String(dto.includePromotions),
    updatedAt: Date.now()
  });

  res.json({ success: true, email: dto.recipientEmail });
});

app.listen(7005);

corrected_code:
const express = require('express');
require('reflect-metadata');
const { plainToInstance } = require('class-transformer');
const { validateOrReject, IsEnum, IsBoolean } = require('class-validator');
const Redis = require('ioredis');

const app = express();
app.use(express.json());
const redis = new Redis(process.env.REDIS_URL);

enum Frequency {
  NONE = 'NONE',
  WEEKLY = 'WEEKLY',
  MONTHLY = 'MONTHLY'
}

class DigestSettingsDto {
  @IsEnum(Frequency)
  frequency;

  @IsBoolean()
  includePromotions;
}

app.put('/api/marketing/digest', async (req, res) => {
  if (!req.user || !req.user.email) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const dto = plainToInstance(DigestSettingsDto, req.body);
  try {
    await validateOrReject(dto);
  } catch (e) {
    return res.status(400).json({ error: 'Invalid digest options' });
  }

  // Bind settings strictly to the authenticated user's email
  const userEmail = req.user.email;

  await redis.hset(`marketing_prefs:${userEmail}`, {
    frequency: dto.frequency,
    includePromotions: String(dto.includePromotions),
    updatedAt: Date.now()
  });

  res.json({ success: true, email: userEmail });
});

app.listen(7005);
